import { eventEnabled, contentVisible } from '../engine/event-visibility.js';

const $ = id => document.getElementById(id);
const CAT = {...window.__PRODUCTS,products:(window.__PRODUCTS?.products||[]).filter(contentVisible)}, FILMS = window.__FILMS?.films || [], MSKINS = window.__SKINS?.skins || [], WYLD = eventEnabled('wyld') ? window.__WYLDROOM?.variants || [] : [], EVENTS = window.__EVENTS || [];
const profile = createProfile();
let adminAccess=false,pendingLockedProduct=null;
const accessForProduct=product=>productAccess(product,{state:ensureProgression(),admin:adminAccess});
const studioAccessReady=currentUser().then(user=>{adminAccess=isAdminUser(user);return adminAccess;}).catch(()=>false);
const touch = matchMedia('(pointer: coarse)').matches || innerWidth < 760;
const RS = renderSettings(profile.get().quality, { lite: touch, dpr: devicePixelRatio });
const reduce = profile.get().motion === 'reduced' || (profile.get().motion === 'auto' && matchMedia('(prefers-reduced-motion: reduce)').matches);
const q = new URLSearchParams(location.search);
const sharedSetup = decodeRaceSetup(q.get('setup'), CAT.products);
const raceSetupStore = createRaceSetupStore();
const event = EVENTS.find(e => e.id === (q.get('event') || sharedSetup?.event_id)) || null;
let raceSetup = sharedSetup || raceSetupStore.load(CAT.products);

// ---------------------------------------------------------------- renderer, camera, stage
const canvas = $('stage');
let renderer;
try { renderer = new THREE.WebGLRenderer({ canvas, antialias: !RS.lite, powerPreference: 'high-performance' }); }
catch (e) { document.body.innerHTML = '<p style="color:#fff;padding:40px;font:16px system-ui">This browser cannot show 3D. <a style="color:#5fd8d3" href="./">Back to the museum</a></p>'; throw e; }
renderer.setPixelRatio(RS.dpr); renderer.toneMapping = THREE.ACESFilmicToneMapping; renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.shadowMap.enabled = RS.shadows; renderer.shadowMap.type = THREE.PCFShadowMap;
const scene = new THREE.Scene();
const pmrem = new THREE.PMREMGenerator(renderer);
scene.environment = pmrem.fromScene(new RoomEnvironment(), .04).texture;
const camera = new THREE.PerspectiveCamera(32, 1, .05, 200);
camera.position.set(2.6, 1.15, 3.1);
const controls = new OrbitControls(camera, canvas);
controls.target.set(0, .55, 0); controls.enableDamping = true; controls.minDistance = 1.3; controls.maxDistance = 7; controls.maxPolarAngle = Math.PI * .52; controls.enablePan = false;
const floor = new THREE.Mesh(new THREE.CircleGeometry(40, 64), new THREE.MeshStandardMaterial({ color: '#e9e2d6', roughness: .9 }));
floor.rotation.x = -Math.PI / 2; floor.receiveShadow = true; scene.add(floor);
const turntable = new THREE.Mesh(new THREE.CylinderGeometry(1.35, 1.4, .06, 64), new THREE.MeshStandardMaterial({ color: '#f4efe7', roughness: .4 }));
turntable.position.y = .03; turntable.receiveShadow = true; scene.add(turntable);
const hemi = new THREE.HemisphereLight('#ffffff', '#bfb3a3', 1.1); scene.add(hemi);
const key = new THREE.DirectionalLight('#ffffff', 2.2); key.position.set(3, 5, 2.5); key.castShadow = true; key.shadow.mapSize.set(RS.lite ? 1024 : 2048, RS.lite ? 1024 : 2048);
Object.assign(key.shadow.camera, { left: -2, right: 2, top: 2, bottom: -2, near: .5, far: 12 }); scene.add(key);
const rim = new THREE.DirectionalLight('#9fd8ff', 1.2); rim.position.set(-3, 2.2, -2.5); scene.add(rim);
const holder = new THREE.Group(); holder.position.y = .06; scene.add(holder);
const loader = new GLTFLoader(); loader.setMeshoptDecoder(MeshoptDecoder);

function sceneTex(top, bottom) {
  const c = document.createElement('canvas'); c.width = 16; c.height = 512; const g = c.getContext('2d');
  const gr = g.createLinearGradient(0, 0, 0, 512); gr.addColorStop(0, top); gr.addColorStop(1, bottom); g.fillStyle = gr; g.fillRect(0, 0, 16, 512);
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; return t;
}
let sceneId = 'studio';
function setScene(id, film) {
  const s = SCENES[id] || SCENES.studio; sceneId = id;
  const top = film ? film.stops[0] : s.sky[0], bottom = film ? film.stops[2] : s.sky[1];
  document.body.style.setProperty('--studio-backdrop',top);
  scene.background?.dispose?.();
  scene.background = sceneTex(top, bottom);
  floor.material.color.set(film ? film.stops[0] : s.floor);
  hemi.intensity = s.hemi; key.intensity = s.key; key.color.set(s.keyColor); rim.color.set(film ? film.stops[4] : s.rim); rim.intensity = s.rimI;
  renderer.toneMappingExposure = s.exposure;
  scene.fog = new THREE.Fog(film ? film.stops[0] : s.sky[1], 9, 30);
  document.body.classList.toggle('light-scene', !!s.light && !film);
}

// ---------------------------------------------------------------- products, looks, loading
const cache = new Map();
let current = null, look = null, loadToken = 0, loadingProduct = false, loadedSelection = null;
const loadModel = url => {
  if (!cache.has(url)) cache.set(url, loader.loadAsync(url).then(g => g.scene).catch(error=>{cache.delete(url);throw error;}));
  const pending=cache.get(url);cache.delete(url);cache.set(url,pending);return pending;
};
function trimModelCache(){
  for(const [url,pending] of cache){
    if(cache.size<=3)break;
    if(url===current?.product.glb)continue;
    cache.delete(url);
    pending.then(model=>model.traverse(o=>{o.geometry?.dispose();for(const m of (Array.isArray(o.material)?o.material:[o.material])){m?.map?.dispose();m?.dispose();}})).catch(()=>{});
  }
}
async function show(product, lookIn) {
  const token = ++loadToken; loadingProduct = true; loadedSelection = null;
  const gate=accessForProduct(product);
  if(!gate.unlocked){
    pendingLockedProduct=product;
    current?.root?.traverse(o=>{for(const m of (Array.isArray(o.material)?o.material:[o.material]))m?.dispose?.();});
    holder.clear();current=null;loadingProduct=false;$('loading').hidden=true;
    $('heroEyebrow').textContent='LOCKED · LEVEL '+gate.requiredLevel;
    $('heroTitle').textContent=product.name;
    $('heroSub').textContent='You can inspect the facts now. The 3D bike unlocks as you explore KONA.';
    drawPanel();
    return false;
  }
  pendingLockedProduct=null; $('loading').hidden = false;
  $('heroEyebrow').textContent = [product.year || product.years || product.era, product.brand].filter(Boolean).join(' · ');
  $('heroTitle').textContent = product.name; $('heroSub').textContent = product.origin === 'studio-design' ? 'Studio design · only in the studio' : product.museum ? 'Also in the museum' : '';
  try {
    const proto = await loadModel(product.glb); if (token !== loadToken) return false;
    const bike = proto.clone(true);
    bike.traverse(o => { if (o.isMesh) { o.material = Array.isArray(o.material) ? o.material.map(m => m.clone()) : o.material.clone(); o.castShadow = true; o.receiveShadow = true; if (o.userData?.optional_accessory) o.visible = false; } });
    const b = new THREE.Box3().setFromObject(bike), c = b.getCenter(new THREE.Vector3()), size = b.getSize(new THREE.Vector3());
    const turned = size.z > size.x;                                  // some pipelines export the bike along z
    const wrap = new THREE.Group(); wrap.add(bike); bike.position.set(-c.x, -b.min.y, -c.z); if (turned) wrap.rotation.y = Math.PI / 2;
    // Cloned materials are per view; geometries/textures remain owned by the bounded model cache.
    current?.root?.traverse(o=>{for(const m of (Array.isArray(o.material)?o.material:[o.material]))m?.dispose?.();});
    holder.clear(); holder.add(wrap);
    current = { product, root: wrap, paint: slotsOf(wrap) };
    applyLook(lookIn || defaultLook(product));
    $('favBtn').setAttribute('aria-pressed', profile.get().favourites.includes(product.id)); $('favBtn').textContent = profile.get().favourites.includes(product.id) ? '♥' : '♡';
    drawPanel();resize();trimModelCache();
    loadedSelection = product.id;
    return true;
  } catch (e) {
    if (token !== loadToken) return false;
    console.warn('studio load', product.id, e);
    toast(navigator.onLine === false ? 'You are offline: this bike has not been cached yet' : 'Could not load this bike · check your connection');
    return false;
  } finally { if (token === loadToken) { loadingProduct = false; $('loading').hidden = true; } }
}
const defaultLook = p => ({ skin: p.skins?.[0] || null, finish: 'gloss', custom: null });
function skinFor(l) {
  const base = l.custom ? { ...(l.skin || {}), ...l.custom, id: 'custom', name: 'Custom', kind: 'studio' } : (l.skin || { id: 'stock', name: 'Stock' });
  const fin = { gloss: { roughness: .22, metalness: .15, clearcoat: 1 }, satin: { roughness: .42, metalness: .1, clearcoat: .4 }, matte: { roughness: .72, metalness: .05, clearcoat: 0 } }[l.finish || 'gloss'];
  return { ...base, finish: { ...fin, ...(base.finish && l.finish === 'gloss' ? base.finish : {}) } };
}
function applyLook(l) {
  if(current&&!contentVisible(l?.skin))l=defaultLook(current.product);
  look = l; if (!current) return;
  const sk = skinFor(l);
  if (sk.frame || sk.dye) applySkin(current.paint, sk);
  const film = l.theme ? FILMS.find(f => f.id === l.theme) : null;
  setScene(film ? 'film' : sceneId, film);
  writeUrl();
}
function writeUrl() {
  if (!current) return;
  const u = new URL(location.href); u.searchParams.set('p', current.product.id);
  const enc = encodeLook(look); if (enc) u.searchParams.set('s', enc); else u.searchParams.delete('s');
  u.searchParams.set('scene', sceneId); if (event) u.searchParams.set('event', event.id);
  history.replaceState(null, '', u);
}

// ---------------------------------------------------------------- panel
let tab = 'bikes', filter = { brand: null, origin: null, q: '' };
const ORIGIN = { 'canyon-model': 'Canyon, current', 'canyon-archive': 'Canyon, archive', 'geometry-study': 'Champions', 'photo-rebuild': 'Named machines', 'type-study': 'Type studies', 'studio-design': 'Studio designs' };
const h = (tag, attrs = {}, ...kids) => { const n = document.createElement(tag); for (const [k, v] of Object.entries(attrs)) { if (k.startsWith('on')) n.addEventListener(k.slice(2), v); else if (v === true) n.setAttribute(k, ''); else if (v != null && v !== false) n.setAttribute(k, v); } for (const k of kids.flat()) if (k != null) n.append(k.nodeType ? k : document.createTextNode(k)); return n; };
