    dreamT += dt; const a = dreamT * .22, r = 3.2 + Math.sin(dreamT * .17) * .6;
    camera.position.set(Math.cos(a) * r, .45 + Math.sin(dreamT * .13) * .35 + .5, Math.sin(a) * r); camera.lookAt(0, .55, 0);
